;static uint16_t  culCalcCRC(uint8_t crcData, uint16_t crcReg)
; 0001 000C {

	.CSEG
_culCalcCRC_G001:
; 0001 000D  uint8_t i;
; 0001 000E  for (i = 0; i < 8; i++)
	ST   -Y,R17
;	crcData -> Y+3
;	crcReg -> Y+1
;	i -> R17
	LDI  R17,LOW(0)
_0x20004:
	CPI  R17,8
	BRLO PC+3
	JMP _0x20005
; 0001 000F  {
; 0001 0010      if (((crcReg & 0x8000) >> 8) ^ (crcData & 0x80))
	LDD  R30,Y+1
	LDD  R31,Y+1+1
	ANDI R30,LOW(0x8000)
	ANDI R31,HIGH(0x8000)
	MOV  R30,R31
	LDI  R31,0
	MOVW R26,R30
	LDD  R30,Y+3
	ANDI R30,LOW(0x80)
	LDI  R31,0
	EOR  R30,R26
	EOR  R31,R27
	SBIW R30,0
	BRNE PC+3
	JMP _0x20006
; 0001 0011      crcReg = (crcReg << 1) ^ CRC16_POLY;
	LDD  R30,Y+1
	LDD  R31,Y+1+1
	LSL  R30
	ROL  R31
	LDI  R26,LOW(32773)
	LDI  R27,HIGH(32773)
	EOR  R30,R26
	EOR  R31,R27
	STD  Y+1,R30
	STD  Y+1+1,R31
; 0001 0012      else
	RJMP _0x20007
_0x20006:
; 0001 0013      crcReg = (crcReg << 1);
	LDD  R30,Y+1
	LDD  R31,Y+1+1
	LSL  R30
	ROL  R31
	STD  Y+1,R30
	STD  Y+1+1,R31
; 0001 0014      crcData <<= 1;
_0x20007:
	LDD  R30,Y+3
	LSL  R30
	STD  Y+3,R30
; 0001 0015  }
_0x20003:
	SUBI R17,-1
	RJMP _0x20004
_0x20005:
; 0001 0016  return crcReg;
	LDD  R30,Y+1
	LDD  R31,Y+1+1
	LDD  R17,Y+0
	ADIW R28,4
	RET
; 0001 0017 } // culCalcCRC
