;static uint16_t CRC16CC1101_Buff(uint8_t *buff, uint8_t length)
; 0001 001C {
_CRC16CC1101_Buff_G001:
; 0001 001D   uint16_t crcresult;
; 0001 001E   uint8_t i;
; 0001 001F   crcresult = CRC16_INIT; // Init value for CRC calculation
	CALL __SAVELOCR4
;	*buff -> Y+5
;	length -> Y+4
;	crcresult -> R16,R17
;	i -> R19
	__GETWRN 16,17,0
; 0001 0020   //crcresult = culCalcCRC(length, crcresult);     //???? Check lai khi test
; 0001 0021   for (i = 0; i < length; i++)
	LDI  R19,LOW(0)
_0x20009:
	LDD  R30,Y+4
	CP   R19,R30
	BRLO PC+3
	JMP _0x2000A
; 0001 0022     crcresult = culCalcCRC(buff[i], crcresult);
	LDD  R26,Y+5
	LDD  R27,Y+5+1
	CLR  R30
	ADD  R26,R19
	ADC  R27,R30
	LD   R30,X
	ST   -Y,R30
	ST   -Y,R17
	ST   -Y,R16
	CALL _culCalcCRC_G001
	MOVW R16,R30
_0x20008:
	SUBI R19,-1
	RJMP _0x20009
_0x2000A:
; 0001 0023 return crcresult;
	MOVW R30,R16
	CALL __LOADLOCR4
	ADIW R28,7
	RET
; 0001 0024 }
