;//--------------------------------------------------------------------------------------
;uint8_t CC1101ReceiveDataMesh(uint8_t *Data, uint8_t *Len)
; 0001 01C4 {
_CC1101ReceiveDataMesh:
; 0001 01C5     uint8_t buff[64];
; 0001 01C6     uint8_t crc_byte_hi, crc_byte_low;
; 0001 01C7     uint16_t crc_byte;
; 0001 01C8 
; 0001 01C9     Signal_RSSI=ReadRegCC1101(0xF4);
	SBIW R28,63
	SBIW R28,1
	CALL __SAVELOCR4
;	*Data -> Y+70
;	*Len -> Y+68
;	buff -> Y+4
;	crc_byte_hi -> R17
;	crc_byte_low -> R16
;	crc_byte -> R18,R19
	LDI  R30,LOW(244)
	ST   -Y,R30
	CALL _ReadRegCC1101
	STS  _Signal_RSSI,R30
; 0001 01CA 
; 0001 01CB     ReadBurstReg(RXFIFO, buff, 64);
	LDI  R30,LOW(63)
	ST   -Y,R30
	CALL SUBOPT_0x49
	LDI  R30,LOW(64)
	ST   -Y,R30
	CALL SUBOPT_0x47
; 0001 01CC     Strobes_Comm(SIDLE);
; 0001 01CD     //Strobes_Comm(SFTX);
; 0001 01CE     Strobes_Comm(SRX);
; 0001 01CF     CC1101SleepMode();
; 0001 01D0 
; 0001 01D1     crc_byte=CRC16CC1101_Buff(buff,buff[0]+1);
	CALL SUBOPT_0x4C
	LDD  R30,Y+6
	SUBI R30,-LOW(1)
	ST   -Y,R30
	CALL _CRC16CC1101_Buff_G001
	MOVW R18,R30
; 0001 01D2     crc_byte_hi=(uint8_t)(crc_byte>>8);
	MOV  R17,R19
; 0001 01D3     crc_byte_low=(uint8_t)(crc_byte&0x00FF);
	MOV  R30,R18
	MOV  R16,R30
; 0001 01D4     if((buff[buff[0]+1]==crc_byte_hi)&&(buff[buff[0]+2]==crc_byte_low))
	LDD  R30,Y+4
	CALL SUBOPT_0x4D
	LD   R26,X
	CP   R17,R26
	BREQ PC+3
	JMP _0x20067
	LDD  R30,Y+4
	CALL SUBOPT_0x4E
	LD   R26,X
	CP   R16,R26
	BREQ PC+3
	JMP _0x20067
	RJMP _0x20068
_0x20067:
	RJMP _0x20066
_0x20068:
; 0001 01D5     {
; 0001 01D6         *Len=buff[0];
	LDD  R30,Y+4
	CALL SUBOPT_0x50
	ST   X,R30
; 0001 01D7         memcpy(Data, buff+1, buff[0]);
	__GETW1SX 70
	CALL SUBOPT_0x51
	LDD  R30,Y+8
	CALL SUBOPT_0x4B
; 0001 01D8         return *Len;
	CALL SUBOPT_0x50
	LD   R30,X
	CALL __LOADLOCR4
	ADIW R28,63
	ADIW R28,9
	RET
; 0001 01D9     }
; 0001 01DA     return 0;
_0x20066:
	LDI  R30,LOW(0)
	CALL __LOADLOCR4
	ADIW R28,63
	ADIW R28,9
	RET
; 0001 01DB }
;
