;uint8_t Seek(uint8_t *Data, uint8_t SeekByte, uint16_t Len)
; 0003 0016 {

	.CSEG
_Seek:
; 0003 0017   uint8_t i;
; 0003 0018   for(i=0;i<Len;i++)
	ST   -Y,R17
;	*Data -> Y+4
;	SeekByte -> Y+3
;	Len -> Y+1
;	i -> R17
	LDI  R17,LOW(0)
_0x60004:
	LDD  R30,Y+1
	LDD  R31,Y+1+1
	CALL SUBOPT_0x53
	CP   R26,R30
	CPC  R27,R31
	BRLO PC+3
	JMP _0x60005
; 0003 0019   {
; 0003 001A     if(SeekByte==*Data)
	LDD  R26,Y+4
	LDD  R27,Y+4+1
	LD   R30,X
	LDD  R26,Y+3
	CP   R30,R26
	BREQ PC+3
	JMP _0x60006
; 0003 001B       return  i;
	MOV  R30,R17
	LDD  R17,Y+0
	ADIW R28,6
	RET
; 0003 001C     else
_0x60006:
; 0003 001D       Data++;
	LDD  R30,Y+4
	LDD  R31,Y+4+1
	ADIW R30,1
	STD  Y+4,R30
	STD  Y+4+1,R31
; 0003 001E   }
_0x60007:
_0x60003:
	SUBI R17,-1
	RJMP _0x60004
_0x60005:
; 0003 001F   return 0;
	LDI  R30,LOW(0)
	LDD  R17,Y+0
	ADIW R28,6
	RET
; 0003 0020 }
