;uint8_t BoardProcessReadCE18G_ByRepeater(void)
; 0003 0232 {
_BoardProcessReadCE18G_ByRepeater:
; 0003 0233     uint8_t Data[32];
; 0003 0234     uint8_t Header[4]={0x00, 0x12, 0x68, 0x12};
; 0003 0235     #ifdef SEND_LOG_RF
