	CALL _CompareBuffer
	CPI  R30,0
	BRNE PC+3
	JMP _0x60096
	CALL SUBOPT_0xAA
	MOVW R30,R28
	ADIW R30,26
	CALL SUBOPT_0xB1
	CALL _CompareBuffer
