; 0003 0241     {
; 0003 0242         #ifdef SEND_LOG_RF
; 0003 0243             sendlogbuffer(text1, 12);
	CALL SUBOPT_0xB0
; 0003 0244         #endif
; 0003 0245        memcpy(MeterCE18G.Reg, Data+12, 4);
