;uint8_t MeshGetData232(uint8_t *Data, uint8_t Len)
; 0008 0023 {
_MeshGetData232:
; 0008 0024     uint8_t i;
; 0008 0025     Meter.Type=Data[4];
	ST   -Y,R17
;	*Data -> Y+2
;	Len -> Y+1
;	i -> R17
	LDD  R26,Y+2
	LDD  R27,Y+2+1
	ADIW R26,4
	LD   R30,X
	STS  _Meter,R30
; 0008 0026     memcpy(Meter.Serial, Data+5, 6);
	__POINTW1MN _Meter,3
	ST   -Y,R31
	ST   -Y,R30
	LDD  R30,Y+4
	LDD  R31,Y+4+1
	ADIW R30,5
	CALL SUBOPT_0xA5
	CALL _memcpy
; 0008 0027     memcpy(MeterCE18G.Serial, Data+12, 4);
	CALL SUBOPT_0xAA
	LDD  R30,Y+4
	LDD  R31,Y+4+1
	ADIW R30,12
	CALL SUBOPT_0xB1
	CALL _memcpy
; 0008 0028     memcpy(time_rec_uart, Data+12, 7);
	LDI  R30,LOW(_time_rec_uart)
	LDI  R31,HIGH(_time_rec_uart)
	ST   -Y,R31
	ST   -Y,R30
	LDD  R30,Y+4
	LDD  R31,Y+4+1
	ADIW R30,12
	CALL SUBOPT_0x13
	CALL _memcpy
; 0008 0029 
; 0008 002A     for(i=0;i<3;i++)
	LDI  R17,LOW(0)
_0x100005:
	CPI  R17,3
	BRLO PC+3
	JMP _0x100006
; 0008 002B     {
; 0008 002C           byte_to_string(time_rec_uart[i], &time_rec_IEC[i*2], &time_rec_IEC[i*2+1]);
	CALL SUBOPT_0x5D
	SUBI R30,LOW(-_time_rec_uart)
	SBCI R31,HIGH(-_time_rec_uart)
	LD   R30,Z
	ST   -Y,R30
	LDI  R30,LOW(2)
	MUL  R30,R17
	MOVW R30,R0
	SUBI R30,LOW(-_time_rec_IEC)
	SBCI R31,HIGH(-_time_rec_IEC)
	ST   -Y,R31
	ST   -Y,R30
	LDI  R30,LOW(2)
	MUL  R30,R17
	MOVW R30,R0
	__ADDW1MN _time_rec_IEC,1
	ST   -Y,R31
	ST   -Y,R30
	CALL _byte_to_string
; 0008 002D     }
_0x100004:
	SUBI R17,-1
	RJMP _0x100005
_0x100006:
; 0008 002E     if(Check_XOR(Data+1, Len-2)) return 1;
	LDD  R30,Y+2
	LDD  R31,Y+2+1
	ADIW R30,1
	ST   -Y,R31
	ST   -Y,R30
	CALL SUBOPT_0xB8
	SBIW R30,2
	ST   -Y,R31
	ST   -Y,R30
	CALL _Check_XOR
	CPI  R30,0
	BRNE PC+3
	JMP _0x100007
	LDI  R30,LOW(1)
	LDD  R17,Y+0
	ADIW R28,4
	RET
; 0008 002F     return 0;
_0x100007:
	LDI  R30,LOW(0)
	LDD  R17,Y+0
	ADIW R28,4
	RET
; 0008 0030 }
