;// SPI initialization
;static void SPI_Init(void)
; 0009 003D {
_SPI_Init_G009:
; 0009 003E     DDRB.1=1;               // SCK=SCLK : output
	SBI  0x17,1
; 0009 003F 
; 0009 0040     DDRB.3=0;               // MISO : input
	CBI  0x17,3
; 0009 0041     PORTB.3=1;
	SBI  0x18,3
; 0009 0042 
; 0009 0043     DDRB.2=1;               // MOSI : output
	SBI  0x17,2
; 0009 0044 
; 0009 0045     DDRB.0=1;               // nSEL : output
	SBI  0x17,0
; 0009 0046 
; 0009 0047     DDRD.0=0;               // GDO2 : input   , nIRQ
	CBI  0x11,0
; 0009 0048 //Si4432
; 0009 0049     PORTD.0=1;
	SBI  0x12,0
; 0009 004A //CC1101
; 0009 004B //    PORTD.0=0;
; 0009 004C 
; 0009 004D //CC1101:input , GDIO0
; 0009 004E //    DDRD.1=0;
; 0009 004F //    PORTD.1=1;
; 0009 0050 //   idle_mode_PA();
; 0009 0051 
; 0009 0052     DDRB.5=1;               // RE_X6: output
	SBI  0x17,5
; 0009 0053     DDRB.4=1;               // TE_X6: output
	SBI  0x17,4
; 0009 0054 
; 0009 0055     #ifdef USE_HHU_G4_HH        //HHU G4 huu hong
; 0009 0056         DDRA.1=1;               // RE_EKEMP: output
	SBI  0x1A,1
; 0009 0057         DDRA.2=1;               // TE_EKEMP: output
	SBI  0x1A,2
; 0009 0058     #else
; 0009 0059         DDRA.0=1;               // RE_EKEMP: output
; 0009 005A         DDRA.1=1;               // TE_EKEMP: output
; 0009 005B     #endif
; 0009 005C 
; 0009 005D     //SPIE = 0:             SPI Interrupt Enable
; 0009 005E     //SPE = 1:              SPI Enable
; 0009 005F     //DORD = 0:             Data Order ; MSB is transmitted first
; 0009 0060     //MSTR = 1:             Master/Slave Select
; 0009 0061     //CPOL = 0:             Clock Polarity  ::: Low
; 0009 0062     //CPHA = 0:             Clock Phase :: Cycle Start
; 0009 0063     //SPR1, SPR0 = 0,0:     SPI Clock Rate Select ::: fosc/4
; 0009 0064     SPCR=0x50;
	LDI  R30,LOW(80)
	OUT  0xD,R30
; 0009 0065 
; 0009 0066     SPSR|=0x00;
	IN   R30,0xE
	OUT  0xE,R30
; 0009 0067     nSEL=1;
	SBI  0x18,0
; 0009 0068 }
	RET
