;
;void Si4432SendDataMesh(uint8_t *Data, uint8_t Len)
; 000A 0121 {
_Si4432SendDataMesh:
; 000A 0122     volatile uint16_t timeout = 0xffff;
; 000A 0123     uint8_t i;
; 000A 0124     #ifdef SEND_LOG_RF
; 000A 0125        uint8_t text[7]="SI4432";
; 000A 0126        sendlogbuffer(text, 6);
	SBIW R28,9
	LDI  R24,9
	LDI  R26,LOW(0)
	LDI  R27,HIGH(0)
	LDI  R30,LOW(_0x140018*2)
	LDI  R31,HIGH(_0x140018*2)
	CALL __INITLOCB
	ST   -Y,R17
;	*Data -> Y+11
;	Len -> Y+10
;	timeout -> Y+8
;	i -> R17
;	text -> Y+1
	CALL SUBOPT_0x92
	CALL SUBOPT_0x11
	CALL _sendlogbuffer
; 000A 0127     #endif
; 000A 0128     LEDGreen();
	CALL _LEDGreen
; 000A 0129     Si4432TxMode();
	CALL _Si4432TxMode
; 000A 012A     WriteRegSi4432(0x3e, Len);
	LDI  R30,LOW(62)
	ST   -Y,R30
	LDD  R30,Y+11
	ST   -Y,R30
	CALL _WriteRegSi4432
; 000A 012B     for(i=0; i<Len; i++)
	LDI  R17,LOW(0)
_0x14001A:
	LDD  R30,Y+10
	CP   R17,R30
	BRLO PC+3
	JMP _0x14001B
; 000A 012C     {
; 000A 012D        WriteRegSi4432(0x7f, Data[i]);
	LDI  R30,LOW(127)
	ST   -Y,R30
	LDD  R26,Y+12
	LDD  R27,Y+12+1
	CALL SUBOPT_0xB4
	ST   -Y,R30
	CALL _WriteRegSi4432
; 000A 012E     }
_0x140019:
	SUBI R17,-1
	RJMP _0x14001A
_0x14001B:
; 000A 012F 
; 000A 0130     Si4432ClearFlag();
	CALL _Si4432ClearFlag
; 000A 0131     Si4432EnableSendData();     //send
	CALL _Si4432EnableSendData_G00A
; 000A 0132     while((nIRQ == 1) & ((--timeout)>0));
_0x14001C:
	LDI  R26,0
	SBIC 0x10,0
	LDI  R26,1
	CALL SUBOPT_0x7D
	LDD  R26,Y+8
	LDD  R27,Y+8+1
	SBIW R26,1
	STD  Y+8,R26
	STD  Y+8+1,R27
	LDI  R30,LOW(0)
	LDI  R31,HIGH(0)
	CALL __GTW12U
	AND  R30,R0
	BRNE PC+3
	JMP _0x14001E
	RJMP _0x14001C
_0x14001E:
; 000A 0133     Si4432ClearFlag();
	CALL _Si4432ClearFlag
; 000A 0134     LEDOff();
	CALL _LEDOff
; 000A 0135 }
	LDD  R17,Y+0
	ADIW R28,13
	RET
;
;
;// tach lay mang du lieu RF nhan duoc
;uint8_t Si4432ReceiveDataMesh(uint8_t *Data, uint8_t *Len)
; 000A 013A {
_Si4432ReceiveDataMesh:
; 000A 013B     uint8_t i;
; 000A 013C     #ifdef SEND_LOG_RF
; 000A 013D         uint8_t text[11]="REC_SI4432";
; 000A 013E         sendlogbuffer(text, 10);
	SBIW R28,11
	LDI  R24,11
	LDI  R26,LOW(0)
	LDI  R27,HIGH(0)
	LDI  R30,LOW(_0x14001F*2)
	LDI  R31,HIGH(_0x14001F*2)
	CALL __INITLOCB
	ST   -Y,R17
;	*Data -> Y+14
;	*Len -> Y+12
;	i -> R17
;	text -> Y+1
	MOVW R30,R28
	ADIW R30,1
	CALL SUBOPT_0x14
; 000A 013F     #endif
; 000A 0140     LEDRed();
	CALL _LEDRed
